impl Solution {
    pub fn detect_capital_use(word: String) -> bool {
        let mut all_upper = true;
        let mut all_lower = true;
        let mut first_upper = true;

        for (i, c) in word.chars().enumerate() {
            if i == 0 {
                if !c.is_uppercase() {
                    first_upper = false;
                }
            } else {
                if c.is_uppercase() {
                    all_lower = false;
                } else {
                    all_upper = false;
                }
            }
        }

        all_upper || all_lower || first_upper
    }
}

